  modal('Ghost curves and geological display anchors',`<form id="pp-ghost"><p>Geological display anchors are separate from logging-run depth matching. Source samples remain unchanged. One accepted marker translates the display; two or more anchors interpolate only inside their evidence interval.</p><label class="field">Source well<select name="source">${wells.map(w=>`<option value="${w.id}" ${w.wellId===editing?.ghostSourceWell?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label class="field">Target well<select name="target">${wells.map(w=>`<option value="${w.id}" ${w.id===selected().well?.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label class="field">Curve names (comma separated; blank means all visible)<input name="curves" value="${esc(editing?.name||'')}"></label><div class="pp-table"><table><thead><tr><th>Accept anchor</th><th>Marker</th><th>Source m</th><th>Target m</th></tr></thead><tbody id="pp-ghost-anchors"></tbody></table></div><p id="pp-ghost-evidence"></p><label class="field">Anchor interpretation / uncertainty<input name="evidence" maxlength="2000" value="${esc(editing?.ghostTransform?.evidence||'')}"></label>${editing?'<label><input name="edit" type="checkbox" checked>Update the selected ghost only</label>':''}<button class="primary">${editing?'Apply reviewed ghost anchors':'Add ghost overlays'}</button></form>`);
