 function markers(){modal('Review individual correlation markers',`<div class="pp-list">${b.markers.map(m=>`<label>${esc(m.name)} · ${esc(m.wellId)} · ${m.depth} ${esc(m.reference||'Unconfirmed')}<input type="checkbox" data-marker="${esc(m.id)}" ${m.accepted?'checked':''}>Accepted interpretation</label>`).join('')||'<p>Pick or import markers before reviewing them.</p>'}</div><p>Acceptance records an interpretation; it does not alter original logging-run depths.</p>`);document.querySelectorAll('[data-marker]').forEach(input=>input.onchange=()=>{const m=b.markers.find(m=>m.id===input.dataset.marker);m.accepted=input.checked;m.reviewedAt=new Date().toISOString();host.save();});}
